<script setup lang="ts">
import{onMounted,reactive,ref}from"vue";import{useRouter}from"vue-router";import{Search,MagicStick}from"@element-plus/icons-vue";import{api}from"@/api";import{useProfileStore}from"@/stores/profile";import{useUserStore}from"@/stores/user";import{err}from"@/utils/format";import type{JobBrief,MatchedJob}from"@/types/api";import PageHeader from"@/components/common/PageHeader.vue";import StateView from"@/components/common/StateView.vue";
const router=useRouter(),user=useUserStore(),profiles=useProfileStore(),filters=reactive({keyword:"",category:""}),jobs=ref<JobBrief[]>([]),matches=ref<MatchedJob[]>([]),loading=ref(false),error=ref(""),matching=ref(false),total=ref(0);const cats=['前端','后端','AI','数据','测试','运维','产品','安全'];async function load(){loading.value=true;error.value="";try{const r=await api.jobs({...filters,page:1,page_size:30});jobs.value=r.items;total.value=r.total}catch(e){error.value=err(e)}finally{loading.value=false}}async function match(){await profiles.load(user.userId!);const skills=profiles.profile?.skills.map(x=>x.name)||[];if(!skills.length){error.value="请先在就业档案中填写至少一项技能";return}matching.value=true;try{matches.value=(await api.match({skills,job_category:filters.category||undefined,top_k:10,user_id:user.userId})).matches}catch(e){error.value=err(e)}finally{matching.value=false}}onMounted(load);
</script>
<template><div><PageHeader title="岗位方向匹配" description="检索真实岗位知识库，并根据就业档案中的技能完成岗位匹配。"><el-button type="primary" :icon="MagicStick" :loading="matching" @click="match">智能匹配</el-button></PageHeader><div class="filter-bar"><el-input v-model="filters.keyword" placeholder="搜索岗位名称或技能" :prefix-icon="Search" clearable @keyup.enter="load"/><el-select v-model="filters.category" placeholder="全部分类" clearable><el-option v-for="x in cats" :key="x" :label="x" :value="x"/></el-select><el-button type="primary" @click="load">搜索</el-button></div><StateView :loading="loading" :error="error" :empty="!(matches.length||jobs.length)" empty-text="没有找到相关岗位" @retry="load"><template #content><div v-if="matches.length" class="result-notice"><b>智能匹配完成</b><span>以下结果由后端知识库与岗位匹配服务计算，不在浏览器端估算。</span><el-button link type="primary" @click="matches=[]">返回岗位列表</el-button></div><div class="job-grid"><article v-for="j in (matches.length?matches:jobs)" :key="j.job_id" class="job-card" @click="router.push(`/jobs/${encodeURIComponent(j.job_id)}`)"><header><div><el-tag size="small" effect="plain">{{j.category||'其他'}}</el-tag><h3>{{j.title}}</h3></div><strong v-if="'match_score' in j">{{(j as MatchedJob).match_score}}<small>%</small></strong></header><p>{{j.snippet||'暂无岗位摘要'}}</p><div class="tag-row"><el-tag v-for="t in j.tags.slice(0,5)" :key="t" size="small" type="info">{{t}}</el-tag></div><template v-if="'match_score' in j"><el-progress :percentage="(j as MatchedJob).match_score" :stroke-width="7"/><div class="match-skills"><span>已具备 {{(j as MatchedJob).matched_skills.length}} 项</span><span>待提升 {{(j as MatchedJob).missing_skills.length}} 项</span></div></template><footer>查看岗位详情 <span>→</span></footer></article></div></template></StateView></div></template>
